import sys
input = sys.stdin.readline

def inp():
	return int(input())

def inlt():
	return list(map(int, input().split()))

def insr():
	s = input()
	return list(s[:len(s) - 1])

def invr():
	return map(int, input().split())

def solve():
	n = inp()
	arr = inlt()
	sor = 0
	ans = n
	st = set()
	for a in arr:
		sor ^= a
		if sor in st or sor == 0:
			ans -= 1
			st.clear()
			sor = 0
		st.add(sor)
	print(ans)
for _ in range(inp()):
	solve()
